package com.aoo.bcg.common.repair;import com.aoo.bcg.common.recovery.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ActiveRoomRepairGuardTest{@Test void requiresCurrentLeaseFencingAndExactSequence()throws Exception{var lease=new RoomLease(9,"repair-node",5,Instant.now().plusSeconds(30));RoomLeaseStore leases=new RoomLeaseStore(){public RoomLease acquire(long id,String n,Duration t){return lease;}public boolean isCurrent(RoomLease candidate){return candidate.equals(lease);}public void release(RoomLease candidate){}};RoomSnapshotStore snapshots=new InMemoryRoomSnapshotStore();snapshots.save(new RoomSnapshot(9,516,"v1","c1",4,7,Instant.now(),Map.of()));var guard=new ActiveRoomRepairGuard(leases,snapshots);var fence=new AtomicLong();assertEquals(8,guard.execute(lease,7,(f,s)->{fence.set(f);return s;}));assertEquals(5,fence.get());assertThrows(IllegalStateException.class,()->guard.execute(lease,6,(f,s)->s));assertThrows(IllegalStateException.class,()->guard.execute(new RoomLease(9,"old",3,Instant.now()),7,(f,s)->s));}}
